-- Extend consented Friends summaries to the full twelve-stamp Passport.
-- Calendar awards use UTC, independent of the caller/database session timezone.
-- Country evidence matches trackingLocationCountry: explicit final fields only,
-- ISO codes or en/de/fr/it region names; ambiguous address abbreviations are rejected.
-- Frozen aliases from Intl.DisplayNames, normalized exactly like the web parser.
create or replace function private.passport_country(p_location text)
returns text language plpgsql immutable strict set search_path = pg_catalog as $function$
declare field text; normalized_field text;
begin
  select btrim(part) into field from regexp_split_to_table(p_location, '[,;|()]') with ordinality as fields(part, ordinal)
    where btrim(part) <> '' order by ordinal desc limit 1;
  if field is null then return null; end if;
  if field = any (string_to_array('AD AE AF AG AI AL AM AO AQ AR AS AT AU AW AX AZ BA BB BD BE BF BG BH BI BJ BL BM BN BO BQ BR BS BT BV BW BY BZ CA CC CD CF CG CH CI CK CL CM CN CO CR CU CV CW CX CY CZ DE DJ DK DM DO DZ EC EE EG EH ER ES ET FI FJ FK FM FO FR GA GB GD GE GF GG GH GI GL GM GN GP GQ GR GS GT GU GW GY HK HM HN HR HT HU ID IE IL IM IN IO IQ IR IS IT JE JM JO JP KE KG KH KI KM KN KP KR KW KY KZ LA LB LC LI LK LR LS LT LU LV LY MA MC MD ME MF MG MH MK ML MM MN MO MP MQ MR MS MT MU MV MW MX MY MZ NA NC NE NF NG NI NL NO NP NR NU NZ OM PA PE PF PG PH PK PL PM PN PR PS PT PW PY QA RE RO RS RU RW SA SB SC SD SE SG SH SI SJ SK SL SM SN SO SR SS ST SV SX SY SZ TC TD TF TG TH TJ TK TL TM TN TO TR TT TV TW TZ UA UG UM US UY UZ VA VC VE VG VI VN VU WF WS YE YT ZA ZM ZW', ' ')) then
    return case when btrim(p_location) = field or not (field = any (string_to_array('AL AZ AR CA CO DE GA ID IL IN KY LA ME MD MA MN MS MO MT NE NC PA SC SD TN VA AG AI BE BL BS FR GE GL GR LU SG SH SO SZ TG NL NU PE SK YT SA', ' '))) then field else null end;
  end if;
  normalized_field := lower(regexp_replace(normalize(field, NFD), U&'[\0300-\036f]', '', 'g'));
  return '{"usa":"US","uk":"GB","andorra":"AD","united arab emirates":"AE","afghanistan":"AF","antigua & barbuda":"AG","anguilla":"AI","albania":"AL","armenia":"AM","angola":"AO","antarctica":"AQ","argentina":"AR","american samoa":"AS","austria":"AT","australia":"AU","aruba":"AW","aland islands":"AX","azerbaijan":"AZ","bosnia & herzegovina":"BA","barbados":"BB","bangladesh":"BD","belgium":"BE","burkina faso":"BF","bulgaria":"BG","bahrain":"BH","burundi":"BI","benin":"BJ","st. barthelemy":"BL","bermuda":"BM","brunei":"BN","bolivia":"BO","caribbean netherlands":"BQ","brazil":"BR","bahamas":"BS","bhutan":"BT","bouvet island":"BV","botswana":"BW","belarus":"BY","belize":"BZ","canada":"CA","cocos (keeling) islands":"CC","congo - kinshasa":"CD","central african republic":"CF","congo - brazzaville":"CG","switzerland":"CH","cote d’ivoire":"CI","cook islands":"CK","chile":"CL","cameroon":"CM","china":"CN","colombia":"CO","costa rica":"CR","cuba":"CU","cape verde":"CV","curacao":"CW","christmas island":"CX","cyprus":"CY","czechia":"CZ","germany":"DE","djibouti":"DJ","denmark":"DK","dominica":"DM","dominican republic":"DO","algeria":"DZ","ecuador":"EC","estonia":"EE","egypt":"EG","western sahara":"EH","eritrea":"ER","spain":"ES","ethiopia":"ET","finland":"FI","fiji":"FJ","falkland islands":"FK","micronesia":"FM","faroe islands":"FO","france":"FR","gabon":"GA","united kingdom":"GB","grenada":"GD","georgia":"GE","french guiana":"GF","guernsey":"GG","ghana":"GH","gibraltar":"GI","greenland":"GL","gambia":"GM","guinea":"GN","guadeloupe":"GP","equatorial guinea":"GQ","greece":"GR","south georgia & south sandwich islands":"GS","guatemala":"GT","guam":"GU","guinea-bissau":"GW","guyana":"GY","hong kong sar china":"HK","heard & mcdonald islands":"HM","honduras":"HN","croatia":"HR","haiti":"HT","hungary":"HU","indonesia":"ID","ireland":"IE","israel":"IL","isle of man":"IM","india":"IN","british indian ocean territory":"IO","iraq":"IQ","iran":"IR","iceland":"IS","italy":"IT","jersey":"JE