create or replace function private.friend_card(p_owner uuid)
returns jsonb language sql stable security definer set search_path = pg_catalog as $$
  with events as (
    select e.package_id, e.stage::text stage, e.occurred_at, e.id, private.passport_country(e.location) country,
      case e.stage::text when 'registered' then 0 when 'accepted' then 1 when 'in_transit' then 2
        when 'customs' then 3 when 'out_for_delivery' then 4 when 'failed_attempt' then 5
        when 'ready_for_pickup' then 6 when 'delivered' then 7 when 'returned' then 8 else -1 end rank
    from public.tracking_events e join public.packages p on p.id = e.package_id
    where p.user_id = p_owner and e.stage::text <> 'pending'
  ), journeys as (
    select package_id,
      bool_and(isfinite(occurred_at)) dates_complete,
      (array_agg(country order by occurred_at, rank, id) filter (where stage <> 'registered'))[1] origin_country,
      (array_agg(country order by occurred_at, rank, id) filter (where stage = 'delivered'))[1] arrival_country,
      (array_agg(stage order by occurred_at desc, rank desc, id desc))[1] stage,
      (array_agg(stage order by occurred_at, rank, id) filter (where stage <> 'registered'))[1] first_stage,
      min(occurred_at) filter (where stage <> 'registered') started,
      min(occurred_at) filter (where stage = 'delivered') arrived
    from events group by package_id
  ), completed as (
    select * from journeys where dates_complete and stage = 'delivered' and arrived <= now()
  ), awards as (
    select
      exists (select 1 from completed j join events a using (package_id) join events b using (package_id)
        where a.stage <> 'registered' and b.stage <> 'registered' and a.occurred_at < b.occurred_at
          and b.occurred_at <= j.arrived and a.country <> b.country) across_borders,
      (select count(distinct origin_country) >= 5 from journeys
        where dates_complete and first_stage in ('accepted','in_transit')) around_world,
      exists (select 1 from completed where first_stage in ('accepted','in_transit')
        and arrived > started and origin_country = arrival_country) domestic,
      exists (select 1 from completed where first_stage in ('accepted','in_transit')
        and extract(epoch from (arrived - started)) > 2592000) long_wait,
      exists (select 1 from completed group by (arrived at time zone 'UTC')::date having count(*) >= 3) busy_day,
      exists (select 1 from completed j join events e using (package_id)
        where e.stage = 'ready_for_pickup' and e.occurred_at < j.arrived) picked_up,
      exists (select 1 from completed where extract(month from arrived at time zone 'UTC') = 12) december
  ), stats as (
    select count(*) filter (where stage = 'delivered')::integer delivered,
      avg(extract(epoch from (arrived - started))) filter (where dates_complete and stage = 'delivered' and first_stage in ('accepted','in_transit') and arrived > started and arrived <= now()) average_seconds,
      min(extract(epoch from (arrived - started))) filter (where dates_complete and stage = 'delivered' and first_stage in ('accepted','in_transit') and arrived > started and arrived <= now()) fastest_seconds,
      coalesce(bool_or(stage = 'delivered' and arrived >= date_trunc('week', now() at time zone 'UTC') at time zone 'UTC' and arrived <= now()), false) this_week
    from journeys
  )
  select jsonb_build_object(
    'id', f.id, 'nickname', f.nickname,
    'stats', case when f.share_stats then jsonb_build_object(
      'deliveredCount', s.delivered,
      'averageDays', case when s.average_seconds is not null then greatest(1, ceil(s.average_seconds / 86400))::integer else null end,
      'stamps', to_jsonb(array_remove(array[
        case when s.delivered >= 1 then 'first' end,
        case when s.delivered >= 10 then 'ten' end,
        case when (select count(distinct carrier) from public.packages where user_id = p_owner) >= 3 then 'connected' end,
        case when s.fastest_seconds <= 172800 then 'express' end,
        case when a.across_borders then 'acrossBorders' end,
        case when a.around_world then 'aroundWorld' end,
        case when s.delivered >= 25 then 'theRegular' end,
        case when a.domestic then 'rightNextDoor' end,
        case when a.long_wait then 'worthTheWait' end,
        case when a.busy_day then 'busyDoorstep' end,
        case when a.picked_up then 'pickedUp' end,
        case when a.december then 'homeForHolidays' end
      ], null))
    ) else null end,
    'arrivedThisWeek', case when f.share_arrival then s.this_week else null end
  ) from public.friend_profiles f cross join stats s cross join awards a where f.user_id = p_owner;
$$;
revoke all on function private.friend_card(uuid) from public, anon, authenticated;
